package org.jlinalg.cli;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.yaml.snakeyaml.Yaml;
import static org.junit.jupiter.api.Assertions.*;

class FumaFisherCliTest {
    @TempDir Path directory;
    private String message;
    private int run(String... args)throws Exception{var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code;try(var stdout=new PrintStream(out,true,StandardCharsets.UTF_8);var stderr=new PrintStream(err,true,StandardCharsets.UTF_8)){code=FumaToolsCli.run(args,stdout,stderr);}message=out.toString(StandardCharsets.UTF_8)+err.toString(StandardCharsets.UTF_8);return code;}
    private int run(Map<String,String> values)throws Exception{var args=new ArrayList<String>();values.forEach((key,value)->{args.add("--"+key);args.add(value);});return run(args.toArray(String[]::new));}
    private static Path out(Map<String,String> options){return Path.of(options.get("out"));}
    private static List<Map<String,String>> table(Path file)throws Exception{var lines=Files.readAllLines(file);String[] header=lines.get(0).split("\t",-1);var rows=new ArrayList<Map<String,String>>();for(String line:lines.subList(1,lines.size())){String[] values=line.split("\t",-1);assertEquals(header.length,values.length);var row=new LinkedHashMap<String,String>();for(int i=0;i<header.length;i++)row.put(header[i],values[i]);rows.add(row);}return rows;}
    private static void replace(Map<String,String> options,String key,String before,String after)throws Exception{Path file=Path.of(options.get(key));String original=Files.readString(file);assertTrue(original.contains(before));Files.writeString(file,original.replace(before,after));}
    private Map<String,String> counts(String name)throws Exception {
        Path base=directory.resolve(name);Files.createDirectories(base);
        Files.writeString(base.resolve("families.tsv"),"family\tcorrection\tencoding\tmissing\tempty\tpseudocount\tconfidence\nF\tBH\tP_VALUE\tEXCLUDE\tRETAIN_SOURCE\t1\t0.95\n");
        Files.writeString(base.resolve("plan.tsv"),"family\ttest_id\nF\ta\nF\tmissing\nF\tempty\n");
        Files.writeString(base.resolve("counts.tsv"),"family\ttest_id\ttrait\tcontext\tfiner_novel\tfiner_known\tcomparator_novel\tcomparator_known\tsource_note\nF\ta\tAD\tClass\t53\t105\t20\t126\tα\nF\tmissing\tT\tmissing\tNA\tNA\tNA\tNA\tβ\nF\tempty\tT\tempty\t0\t0\t57\t340\tγ\n");
        var options=new LinkedHashMap<String,String>();options.put("method","fisher-enrichment");options.put("mode","counts");options.put("analysis-id","synthetic-complete-family");options.put("cutoff","0.05");for(String key:List.of("families","plan","counts"))options.put(key,base.resolve(key+".tsv").toString());options.put("out",base.resolve("analysis").toString());return options;
    }
    private void failed(Map<String,String> options)throws Exception {assertEquals(2,run(options),message);assertTrue(message.contains("Required action:"));assertTrue(Files.readString(out(options).resolve("analysis-status.json")).contains("failed"));assertTrue(Files.isDirectory(out(options).resolve("partial")));assertFalse(Files.exists(out(options).resolve("fisher-tables.tsv")));}
    private Map<String,String> known(String name,String matching)throws Exception{var options=FumaAssociationTestData.options(directory.resolve(name));replace(options,"sources","B\tBASELINE","B\tTARGET");options.put("matching",matching);assertEquals(0,run(options),message);return options;}
    private Map<String,String> groups(String name,Map<String,String> known)throws Exception {
        var options=counts(name);options.remove("counts");options.put("mode","groups");options.put("known-bundle",out(known).toString());options.put("gene-namespace","gene-v1");options.put("trait-namespace","trait-v1");options.put("matching",known.get("matching"));options.put("unassessable","exclude");
        Path base=out(options).getParent();Files.writeString(Path.of(options.get("plan")),"family\ttest_id\nF\tpooled\n");Files.writeString(base.resolve("groups.tsv"),"group\tsource\ttrait\tcontext\texpected_rows\nbulk\tB\tT1\tbulk\t1\nbulk\tB\tT2\tbulk\t2\nfiner\tT\tT1\tclass1\t2\nfiner\tT\tT2\tclass2\t2\n");
        Files.writeString(base.resolve("comparisons.tsv"),"family\ttest_id\ttrait\tcontext\tfiner_group\tcomparator_group\toverlap\nF\tpooled\tAll\tClass\tfiner\tbulk\tFINER_ONLY\n");options.put("groups",base.resolve("groups.tsv").toString());options.put("comparisons",base.resolve("comparisons.tsv").toString());return options;
    }
    private static void refresh(Path bundle,String member)throws Exception {Path file=bundle.resolve("manifest.yaml");Map<?,?> raw=new Yaml().load(Files.readString(file));var manifest=new LinkedHashMap<Object,Object>(raw);var outputs=new LinkedHashMap<Object,Object>((Map<?,?>)manifest.get("output_sha256"));outputs.put(member,FollowupSupport.hash(bundle.resolve(member)));manifest.put("output_sha256",outputs);Files.writeString(file,new Yaml().dump(manifest));}
    private Path parent(Map<String,String> fisher,Map<String,Object> other)throws Exception{var stage=new LinkedHashMap<>(fisher);stage.remove("out");var root=new LinkedHashMap<String,Object>();root.put("schema_version",1);root.put("build","GRCh37");root.put("out","workflow");root.put("fisher_enrichment",stage);root.putAll(other);return FumaAssociationTestData.carrier(out(fisher).getParent().resolve("parent.json"),root);}
    @Test void countWorkflowRetainsMissingEmptyOriginalsAndConditionalRootEvidence()throws Exception {
        var options=counts("counts");assertEquals(0,run(options),message);var rows=table(out(options).resolve("fisher-tables.tsv"));assertEquals(3,rows.size());assertEquals("MISSING_COUNTS",rows.get(1).get("status"));assertEquals("NA",rows.get(1).get("selected"));assertEquals("EMPTY_ORIGINAL_GROUP_RETAINED",rows.get(2).get("status"));assertEquals("0",rows.get(2).get("original_finer_novel"));assertEquals("1",rows.get(2).get("tested_finer_novel"));assertEquals(6.27679302214557e-5,Double.parseDouble(rows.get(0).get("p")),2e-18);assertEquals(3.06968525907479,Double.parseDouble(rows.get(0).get("conditional_odds_ratio")),1e-13);assertEquals("2",table(out(options).resolve("family-audit.tsv")).get(0).get("computed_adjustment_size"));assertEquals(3,table(out(options).resolve("planned-tests.tsv")).size());assertFalse(table(out(options).resolve("root-audit.tsv")).isEmpty());assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("R DEFAULT ROOT PROTOCOL"));assertFalse(Files.readString(out(options).resolve("fisher-tables.tsv")).contains("NaN"));
    }
    @Test void missingCountTablesRequireFourNAAndAnExplicitExclusionPolicy()throws Exception {var options=counts("partial-na");replace(options,"counts","NA\tNA\tNA\tNA","NA\tNA\t0\tNA");failed(options);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("all four"));options=counts("no-exclude");replace(options,"families","EXCLUDE","ERROR");failed(options);}
    @Test void exactCountsRefuseDecimalsSignsSpacesOverflowAndMissingAliases()throws Exception{int i=0;for(String invalid:List.of("-1","+1","1.0","1e2"," 53","NaN","Inf","null","9223372036854775808")){var options=counts("bad-count-"+i++);replace(options,"counts","53\t105",invalid+"\t105");failed(options);}}
    @Test void completePlanAndFamilyIdentitiesAreEnforcedBeforeSelection()throws Exception{var options=counts("incomplete");replace(options,"plan","F\ta\n","F\ta\nF\tmissing-id\n");failed(options);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("Incomplete declared"));options=counts("duplicate");replace(options,"plan","F\ta\n","F\ta\nF\ta\n");failed(options);options=counts("unknown");replace(options,"counts","F\ta\tAD","unknown\ta\tAD");failed(options);}
    @Test void pseudocountNeverHidesAnOriginalEmptyGroup()throws Exception{var options=counts("empty-policy");replace(options,"families","RETAIN_SOURCE","ERROR");failed(options);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("does not create observed associations"));}
    @Test void finiteLogAdjustmentPreservesProbabilityUnderflow()throws Exception{var options=counts("log");Files.writeString(Path.of(options.get("plan")),"family\ttest_id\nF\tx\n");Files.writeString(Path.of(options.get("counts")),"family\ttest_id\ttrait\tcontext\tfiner_novel\tfiner_known\tcomparator_novel\tcomparator_known\nF\tx\tT\tC\t2000\t0\t0\t2000\n");replace(options,"families","P_VALUE","NATURAL_LOG");assertEquals(0,run(options),message);var row=table(out(options).resolve("fisher-tables.tsv")).get(0);assertEquals("0.0",row.get("p"));assertEquals("0.0",row.get("adjusted_p"));assertTrue(Double.isFinite(Double.parseDouble(row.get("ln_p"))));assertTrue(Double.isFinite(Double.parseDouble(row.get("adjusted_ln_p"))));assertEquals("1",table(out(options).resolve("family-audit.tsv")).get(0).get("adjusted_probability_underflows"));}
    @Test void CRLFAndExtraColumnsRemainInExactCarrierRelativeSnapshots()throws Exception{var options=counts("relative-β");Path base=out(options).getParent();for(String key:List.of("families","plan","counts")){Path file=Path.of(options.get(key));Files.writeString(file,Files.readString(file).replace("\n","\r\n"));options.put(key,file.getFileName().toString());}options.put("out","analysis");Path carrier=FumaAssociationTestData.carrier(base.resolve("fisher.json"),options);assertEquals(0,run("--fisher-options-file",carrier.toString()),message);var ledger=table(base.resolve("analysis/resource-ledger.tsv"));assertEquals(4,ledger.size());for(var row:ledger)assertArrayEquals(Files.readAllBytes(Path.of(row.get("source"))),Files.readAllBytes(base.resolve("analysis").resolve(row.get("snapshot"))));assertTrue(Files.readString(base.resolve("analysis/source-inputs/i0004.raw")).contains("α\r\n"));}
    @Test void malformedUTF8HeadersAndControlFieldsAreRefused()throws Exception{var options=counts("utf8");Files.write(Path.of(options.get("counts")),new byte[]{(byte)0xc3,(byte)0x28});failed(options);options=counts("duplicate-header");replace(options,"counts","source_note","trait");failed(options);options=counts("control");replace(options,"counts","Class","Class\u0000");failed(options);}
    @Test void allInputOutputSupportAndWorkLimitsRefuseWholeResults()throws Exception{for(var entry:Map.of("max-rows","1","max-cells","1","max-snapshot-bytes","1","max-output-bytes","1","max-output-rows","1","max-operations","1","max-support","1","max-support-states","1","max-population","1").entrySet()){var options=counts(entry.getKey());options.put(entry.getKey(),entry.getValue());failed(options);}}
    @Test void unknownRecursiveAndNonStringCarriersAreRejectedBeforeOutput()throws Exception{for(String key:List.of("fisher-options-file","unknown","max-rows")){var options=counts("bad-carrier-"+key);var raw=new LinkedHashMap<String,Object>(options);raw.put(key,key.equals("max-rows")?10:"bad");Path carrier=FumaAssociationTestData.carrier(out(options).getParent().resolve("fisher.json"),raw);assertEquals(2,run("--fisher-options-file",carrier.toString()),message);assertFalse(Files.exists(out(options)));}}
    @Test void existingOutputAndConflictingModesAreProtected()throws Exception{var options=counts("exists");assertEquals(0,run(options),message);String before=FollowupSupport.hash(out(options).resolve("fisher-tables.tsv"));assertEquals(2,run(options));assertEquals(before,FollowupSupport.hash(out(options).resolve("fisher-tables.tsv")));options=counts("unused");options.put("matching","gene-trait");assertEquals(2,run(options));assertFalse(Files.exists(out(options)));}
    @Test void verifiedKnownBundlePreservesClassificationsNamespacesBuildsAndEveryGroupRow()throws Exception{var upstream=known("known","gene-trait");String original=FollowupSupport.hash(out(upstream).resolve("all-tests.tsv"));var options=groups("grouped",upstream);assertEquals(0,run(options),message);assertEquals(original,FollowupSupport.hash(out(upstream).resolve("all-tests.tsv")));var row=table(out(options).resolve("fisher-tables.tsv")).get(0);assertEquals("1",row.get("original_finer_novel"));assertEquals("1",row.get("original_finer_known"));assertEquals("1",row.get("original_comparator_novel"));assertEquals("0",row.get("original_comparator_known"));assertEquals(7,table(out(options).resolve("group-dispositions.tsv")).size());assertEquals(5,table(out(options).resolve("group-contributors.tsv")).size());assertTrue(table(out(options).resolve("unassigned-targets.tsv")).isEmpty());assertEquals(List.of("GRCh37","GRCh38","GRCh38"),table(out(options).resolve("known-association-sources.tsv")).stream().map(r->r.get("genome_build")).toList());assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("UPSTREAM KNOWN ASSOCIATIONS"));}
    @Test void geneUnionsPreserveOriginalProjectionAndAllSharedContributors()throws Exception{var options=groups("pooled",known("known-pooled","gene-across-traits"));assertEquals(0,run(options),message);var row=table(out(options).resolve("fisher-tables.tsv")).get(0);assertEquals("2",row.get("original_finer_novel"));assertEquals("0",row.get("original_finer_known"));assertEquals(1,table(out(options).resolve("shared-keys.tsv")).size());assertEquals(2,table(out(options).resolve("shared-contributors.tsv")).size());assertEquals("NA",table(out(options).resolve("shared-keys.tsv")).get(0).get("matched_trait"));}
    @Test void matchingAndNamespaceChangesRequireRecomputedOriginalClassifications()throws Exception{var upstream=known("known-mode","gene-trait");for(String key:List.of("matching","gene-namespace","trait-namespace")){var options=groups("mismatch-"+key,upstream);options.put(key,key.equals("matching")?"gene-across-traits":"other");failed(options);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("differs"));}}
    @Test void changedOrIncompleteBundleMembersCannotBeImported()throws Exception{var upstream=known("known-changed","gene-trait");Files.writeString(out(upstream).resolve("all-tests.tsv"),Files.readString(out(upstream).resolve("all-tests.tsv"))+"altered\n");var options=groups("changed",upstream);failed(options);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("SHA-256 differs"));upstream=known("known-extra","gene-trait");Files.writeString(out(upstream).resolve("extra.txt"),"unmanifested");failed(groups("extra",upstream));upstream=known("known-missing","gene-trait");Files.delete(out(upstream).resolve("known-links.tsv"));failed(groups("missing-member",upstream));}
    @Test void failedMarkersAndForgedTargetProvenanceAreRejectedEvenWithUpdatedHashes()throws Exception{var upstream=known("known-status","gene-trait");Files.writeString(out(upstream).resolve("analysis-status.json"),"{\"status\":\"failed\",\"exit_code\":2}\n");refresh(out(upstream),"analysis-status.json");failed(groups("failed-status",upstream));upstream=known("known-forged","gene-trait");Path decisions=out(upstream).resolve("target-decisions.tsv");Files.writeString(decisions,Files.readString(decisions).replace("G1\tT1\tclass1","wrong\tT1\tclass1"));refresh(out(upstream),"target-decisions.tsv");var options=groups("forged",upstream);failed(options);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("provenance differs"));}
    @Test void unsafeManifestMembersAndUnboundedBundlePopulationsAreRefused()throws Exception{var upstream=known("known-path","gene-trait");Path manifest=out(upstream).resolve("manifest.yaml");Files.writeString(manifest,Files.readString(manifest).replace("all-tests.tsv:","../escape.tsv:"));failed(groups("unsafe",upstream));var options=groups("file-budget",known("known-file-budget","gene-trait"));options.put("max-bundle-files","1");failed(options);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("max-bundle-files"));}
    @Test void missingUnselectedAndUnassignedSourceRowsRemainVisible()throws Exception{var upstream=FumaAssociationTestData.options(directory.resolve("known-missing-target"));replace(upstream,"sources","B\tBASELINE","B\tTARGET");replace(upstream,"families","C\tT\tP_VALUE\tBH\tERROR","C\tT\tP_VALUE\tBH\tEXCLUDE");replace(upstream,"tests","class2\t0.002","class2\tNA");assertEquals(0,run(upstream),message);var options=groups("missing-target",upstream);replace(options,"groups","finer\tT\tT2\tclass2\t2\n","");assertEquals(0,run(options),message);assertEquals(2,table(out(options).resolve("unassigned-targets.tsv")).size());assertTrue(table(out(options).resolve("unassigned-targets.tsv")).stream().anyMatch(r->r.get("decision").equals("MISSING_TARGET_VALUE")));options.put("out",out(options).resolveSibling("no-exclude").toString());options.put("unassessable","error");failed(options);}
    @Test void parentIndependentFisherRunsAfterFailureAndRetainsFailedParentStatus()throws Exception{var options=counts("parent-failed");Path recipe=parent(options,Map.of("variant_annotation",Map.of("build","GRCh37")));assertEquals(2,run("--workflow-options-file",recipe.toString()),message);Path root=recipe.getParent().resolve("workflow");assertTrue(Files.isRegularFile(root.resolve("fisher-enrichment/fisher-tables.tsv")));assertTrue(Files.readString(root.resolve("analysis-status.json")).contains("failed"));}
    @Test void parentIndependentFisherRunsAfterUnavailableMagmaAndRetainsSkipStatus()throws Exception{var options=counts("parent-skipped");Path base=out(options).getParent();var annotation=Map.of("method","annotate","home",base.resolve("missing-home").toString(),"snps",base.resolve("missing-snps").toString(),"genes",base.resolve("missing-genes").toString());Path recipe=parent(options,Map.of("magma_annotate",annotation));assertEquals(3,run("--workflow-options-file",recipe.toString()),message);assertTrue(Files.isRegularFile(base.resolve("workflow/fisher-enrichment/fisher-tables.tsv")));assertTrue(Files.readString(base.resolve("workflow/magma-annotation/WARNINGS.md")).contains("Required action"));}
    @Test void parentExplicitKnownBridgeSealsActualUpstreamPathsAndPropagatesFailure()throws Exception{var upstream=known("known-parent","gene-trait");var options=groups("parent-bridge",upstream);options.remove("known-bundle");var knownStage=new LinkedHashMap<>(upstream);knownStage.remove("out");Path recipe=parent(options,Map.of("known_associations",knownStage,"fisher_known_source","known-associations-stage"));assertEquals(0,run("--workflow-options-file",recipe.toString()),message);Path root=recipe.getParent().resolve("workflow");assertTrue(Files.isRegularFile(root.resolve("fisher-enrichment/fisher-tables.tsv")));assertTrue(Files.readString(root.resolve("fisher-enrichment/session.json")).contains("known-associations"));var bad=counts("parent-bridge-failed");bad.remove("counts");for(String key:List.of("mode","gene-namespace","trait-namespace","matching","unassessable","groups","comparisons"))bad.put(key,options.get(key));knownStage.put("tests",directory.resolve("missing-tests.tsv").toString());recipe=parent(bad,Map.of("known_associations",knownStage,"fisher_known_source","known-associations-stage"));assertEquals(2,run("--workflow-options-file",recipe.toString()),message);root=recipe.getParent().resolve("workflow");assertTrue(Files.readString(root.resolve("fisher-enrichment/analysis-status.json")).contains("skipped-upstream"));assertFalse(Files.exists(root.resolve("fisher-enrichment/fisher-tables.tsv")));}
    @Test void parentRejectsConflictingBridgeAndMethodOverridesBeforeOutput()throws Exception{var options=counts("parent-conflict");Path recipe=parent(options,Map.of("fisher_known_source","known-associations-stage"));assertEquals(2,run("--workflow-options-file",recipe.toString()),message);assertFalse(Files.exists(recipe.getParent().resolve("workflow")));options=counts("parent-method");options.put("method","other");recipe=parent(options,Map.of());assertEquals(2,run("--workflow-options-file",recipe.toString()),message);assertFalse(Files.exists(recipe.getParent().resolve("workflow")));}
    @Test void helpShowsExplicitPoliciesAndGroupEvidence()throws Exception{assertEquals(0,run("--method","fisher-enrichment","--help"));assertTrue(message.contains("FINER_ONLY"));assertTrue(message.contains("RETAIN_SOURCE"));assertTrue(message.contains("--max-support-states"));assertTrue(message.contains("conditional"));assertEquals(0,run("--help"));assertTrue(message.contains("--method fisher-enrichment --help"));}
}
